package com.ssk.kiosk.integration;
import jakarta.persistence.*;import java.time.Instant;
@Entity public class IntegrationConfiguration {
 @Id private String integrationKey; private boolean enabled; private String baseUrl; private String verificationPath; private String approvalField; private String approvalValue; @Lob private String workflowSnapshot; private String executionMode; private int connectTimeoutMs; private int readTimeoutMs; private int retryCount; private Instant updatedAt; private String updatedBy; @Version private Long rowVersion;
 public String getIntegrationKey(){return integrationKey;} public void setIntegrationKey(String v){integrationKey=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getBaseUrl(){return baseUrl;} public void setBaseUrl(String v){baseUrl=v;} public String getVerificationPath(){return verificationPath;} public void setVerificationPath(String v){verificationPath=v;} public String getApprovalField(){return approvalField;} public void setApprovalField(String v){approvalField=v;} public String getApprovalValue(){return approvalValue;} public void setApprovalValue(String v){approvalValue=v;} public String getWorkflowSnapshot(){return workflowSnapshot;} public void setWorkflowSnapshot(String v){workflowSnapshot=v;} public String getExecutionMode(){return executionMode;} public void setExecutionMode(String v){executionMode=v;} public int getConnectTimeoutMs(){return connectTimeoutMs;} public void setConnectTimeoutMs(int v){connectTimeoutMs=v;} public int getReadTimeoutMs(){return readTimeoutMs;} public void setReadTimeoutMs(int v){readTimeoutMs=v;} public int getRetryCount(){return retryCount;} public void setRetryCount(int v){retryCount=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} public String getUpdatedBy(){return updatedBy;} public void setUpdatedBy(String v){updatedBy=v;} public Long getRowVersion(){return rowVersion;}
}
